<?php $pageTitle='Login';require __DIR__.'/includes/header.php';if(current_user()) redirect(dashboard_for_role(current_user()['role']));if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[^@\s]+@[^@\s]+\.[A-Za-z]{2,63}$/',$email)||$pass===''){flash('error','Enter a valid email and password.');}else{$s=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pass,$u['password'])&&$u['status']==='active'){login_user($u);log_activity((int)$u['id'],'login','user',(int)$u['id']);redirect(dashboard_for_role($u['role']));}log_activity($u?(int)$u['id']:null,'login_failed',null,null,'email='.substr($email,0,120));flash('error','Invalid credentials or inactive account.');}}?><div class="auth-wrap"><div class="form-card auth-card"><h1>Welcome back</h1><form method="post"><div class="field"><label>Email</label><input type="email" name="email" required autocomplete="email"></div><div class="field"><label>Password</label><input type="password" name="password" required autocomplete="current-password"></div><?=csrf_field()?><button class="btn" style="width:100%">Login</button></form><p><a href="<?=url('forgot-password.php')?>">Forgot password?</a></p><p>New here? <a href="<?=url('register.php')?>">Create an account</a></p></div></div><?php require __DIR__.'/includes/footer.php';?>
